   354	/****************************************************************************
   355	 * Name: greeting_style
   356	 *
   357	 * Description:
   358	 *   The pen and layout the boot greeting is drawn with.  These are the same
   359	 *   numbers as 'hello em=52 thick=4', so the boot animation and the shell
   360	 *   command produce the same strokes -- they now share one renderer
   361	 *   (hello_paint.c) and one stroke font (hello_font.c) instead of the panel
   362	 *   driver carrying its own 5x7 bitmap copy of the word.
   363	 *
   364	 ****************************************************************************/
   365	
   366	#define GC9D01_GREETING_TEXT   "hello vela"
   367	#define GC9D01_GREETING_EM     52
   368	#define GC9D01_GREETING_THICK  4
   369	#define GC9D01_GREETING_STEPS  20
   370	
   371	static int32_t greeting_style(FAR struct hs_style_s *st)
   372	{
   373	  int32_t budget = (GC9D01_XRES * 16 * 85) / 100;
   374	  int32_t width = 0;
   375	  int32_t total;
   376	
   377	  memset(st, 0, sizeof(*st));
   378	  st->fg      = 0xffff;
   379	  st->bg      = 0x0000;
   380	  st->em16    = GC9D01_GREETING_EM * 16;
   381	  st->thick16 = GC9D01_GREETING_THICK * 16;
   382	
   383	  /* Baseline is nudged below the centre by the same fraction the command
   384	   * uses, so the word sits optically centred rather than mathematically.
   385	   */
   386	
   387	  st->baseline16 = (GC9D01_YRES * 16) / 2 + (st->em16 * 10) / 64;
   388	  total = hs_measure(GC9D01_GREETING_TEXT, st, &width);
   389	
   390	  /* Auto-fit, same 85% chord budget as the shell command.  The glass is
   391	   * round, so the usable width is a chord rather than the full 160 pixels,
   392	   * and GC9D01_GREETING_EM is the requested size rather than a promise: at
   393	   * em 52 "hello vela" is about 180 pixels wide and would lose its first
   394	   * letter off the left edge, which looks like a font bug rather than an
   395	   * overflow.
   396	   */
   397	
   398	  if (width > budget && width > 0)
   399	    {
   400	      st->em16 = (st->em16 * budget) / width;
   401	      st->thick16 = (st->thick16 * budget) / width;
   402	
   403	      if (st->thick16 < 2 * 16)
   404	        {
   405	          st->thick16 = 2 * 16;
   406	        }
   407	
   408	      st->baseline16 = (GC9D01_YRES * 16) / 2 + (st->em16 * 10) / 64;
   409	      total = hs_measure(GC9D01_GREETING_TEXT, st, &width);
   410	    }
   411	
   412	  st->cx16 = (GC9D01_XRES * 16 - width) / 2;
   413	  return total;
   414	}
