   416	/****************************************************************************
   417	 * Name: bk7258_gc9d01_fb_hello
   418	 *
   419	 * Description:
   420	 *   The greeting, complete, in one shot.  Kept for callers that cannot
   421	 *   animate; the boot path uses bk7258_gc9d01_fb_hello_animate().
   422	 *
   423	 ****************************************************************************/
   424	
   425	int bk7258_gc9d01_fb_hello(int display)
   426	{
   427	  FAR struct gc9d01_fb_s *priv;
   428	  struct hs_style_s st;
   429	  int32_t total;
   430	
   431	  if (display < 0 || display >= GC9D01_NDISPLAYS)
   432	    {
   433	      return -EINVAL;
   434	    }
   435	
   436	  priv = &g_gc9d01_fb[display];
   437	  if (priv->fbmem == NULL)
   438	    {
   439	      return -ENODEV;
   440	    }
   441	
   442	  total = greeting_style(&st);
   443	
   444	  hs_clear(priv->fbmem, GC9D01_STRIDE, GC9D01_XRES, GC9D01_YRES, &st);
   445	  hs_stroke(priv->fbmem, GC9D01_STRIDE, GC9D01_XRES, GC9D01_YRES,
   446	            GC9D01_GREETING_TEXT, &st, 0, total);
   447	
   448	  return gc9d01_push(priv);
   449	}
   450	
   451	/****************************************************************************
   452	 * Name: bk7258_gc9d01_fb_hello_animate
   453	 *
   454	 * Description:
   455	 *   Writes the greeting one pen stroke at a time, all selected panels
   456	 *   advancing together, which is what the 'hello' shell command does.
   457	 *
   458	 *   displays is a bitmask of panels.  Only the newly written stroke is drawn
   459	 *   each step -- the pen adds ink and never repaints -- so a step costs one
   460	 *   short stroke plus a full-frame push per panel.  The panel takes no
   461	 *   partial update (see gc9d01_updatearea()), so the push dominates and sets
   462	 *   the pace; the elapsed time is reported to keep that cost visible in the
   463	 *   boot log.
   464	 *
   465	 *   Reusing the command's renderer was not possible while it lived with the
   466	 *   application: bring-up cannot start an application in this configuration
   467	 *   (neither exec_builtin() nor posix_spawn() is built), which showed up as
   468	 *   an undefined reference at link time.  Moving the renderer to the board is
   469	 *   what made one implementation serve both.
   470	 *
   471	 ****************************************************************************/
   472	
   473	int bk7258_gc9d01_fb_hello_animate(int displays, int steps)
   474	{
   475	  struct hs_style_s st;
   476	  clock_t start = clock_systime_ticks();
   477	  int32_t total;
   478	  int32_t drawn = 0;
   479	  int display;
   480	  int step;
   481	  int drew = 0;
   482	
   483	  if (steps < 1)
   484	    {
   485	      steps = 1;
   486	    }
   487	
   488	  total = greeting_style(&st);
   489	  if (total <= 0)
   490	    {
   491	      return -EINVAL;
   492	    }
   493	
   494	  for (display = 0; display < GC9D01_NDISPLAYS; display++)
   495	    {
   496	      if ((displays & (1 << display)) != 0 &&
   497	          g_gc9d01_fb[display].fbmem != NULL)
   498	        {
   499	          hs_clear(g_gc9d01_fb[display].fbmem, GC9D01_STRIDE,
   500	                   GC9D01_XRES, GC9D01_YRES, &st);
   501	          (void)gc9d01_push(&g_gc9d01_fb[display]);
   502	          drew = 1;
   503	        }
   504	    }
   505	
   506	  if (drew == 0)
   507	    {
   508	      return -ENODEV;
   509	    }
   510	
   511	  for (step = 1; step <= steps; step++)
   512	    {
   513	      /* Same smoothstep the command uses, so the pen accelerates into the
   514	       * stroke and settles out of it rather than moving at a constant rate.
   515	       */
   516	
   517	      int32_t target = (int32_t)(((int64_t)total *
   518	                        hs_ease((step * 1000) / steps)) / 1000);
   519	      FAR uint8_t *master = NULL;
   520	
   521	      if (step >= steps)
   522	        {
   523	          target = total;
   524	        }
   525	
   526	      if (target <= drawn)
   527	        {
   528	          continue;
   529	        }
   530	
   531	      for (display = 0; display < GC9D01_NDISPLAYS; display++)
   532	        {
   533	          if ((displays & (1 << display)) == 0 ||
   534	              g_gc9d01_fb[display].fbmem == NULL)
   535	            {
   536	              continue;
   537	            }
   538	
   539	          /* Rasterize once, then copy.  Both panels show the same word and
   540	           * have identical geometry and stride, so stroking each of them
   541	           * separately would pay for the same pixels twice: measured at
   542	           * ~1.8ms per path pixel, the second pass cost about as much as a
   543	           * full frame push.  memcpy of 51200 bytes between two kernel-RAM
   544	           * framebuffers is far cheaper.
   545	           */
   546	
   547	          if (master == NULL)
   548	            {
   549	              hs_stroke(g_gc9d01_fb[display].fbmem, GC9D01_STRIDE,
   550	                        GC9D01_XRES, GC9D01_YRES, GC9D01_GREETING_TEXT, &st,
   551	                        drawn, target);
   552	              master = g_gc9d01_fb[display].fbmem;
   553	            }
   554	          else
   555	            {
   556	              memcpy(g_gc9d01_fb[display].fbmem, master, GC9D01_FBLEN);
   557	            }
   558	
   559	          (void)gc9d01_push(&g_gc9d01_fb[display]);
   560	        }
   561	
   562	      drawn = target;
   563	    }
   564	
   565	  printf("gc9d01_fb: greeting written in %lu ms (%d steps, %d px path, "
   566	         "em %d, pen %d)\n",
   567	         (unsigned long)TICK2MSEC(clock_systime_ticks() - start), steps,
   568	         (int)(total / 16), (int)(st.em16 / 16), (int)(st.thick16 / 16));
   569	
   570	  return OK;
   571	}
