   573	/****************************************************************************
   574	 * Name: bk7258_gc9d01_fb_text / bk7258_gc9d01_fb_two_lines
   575	 *
   576	 * Description:
   577	 *   Draw one word, or two lines, and push once.  These are what the
   578	 *   event-driven status screen uses (bk7258_status_screen.c): the product
   579	 *   spec forbids a live preview and asks for a state plus a one-or-two-line
   580	 *   summary, refreshed only when it changes.
   581	 *
   582	 *   Sized to the panel rather than to the text: a 160x160 round display shows
   583	 *   roughly six characters per line at a legible stroke width, so callers
   584	 *   are expected to have shortened the text already.  Text the font cannot
   585	 *   draw returns -EINVAL instead of an empty screen.
   586	 *
   587	 ****************************************************************************/
   588	
   589	static int gc9d01_fb_lines(int display, FAR const char *const *lines,
   590	                           int nlines, uint16_t fg)
   591	{
   592	  FAR struct gc9d01_fb_s *priv;
   593	  struct hs_style_s st;
   594	  int i;
   595	
   596	  if (display < 0 || display >= GC9D01_NDISPLAYS || nlines < 1)
   597	    {
   598	      return -EINVAL;
   599	    }
   600	
   601	  priv = &g_gc9d01_fb[display];
   602	  if (priv->fbmem == NULL)
   603	    {
   604	      return -ENODEV;
   605	    }
   606	
   607	  memset(&st, 0, sizeof(st));
   608	  st.fg = fg;
   609	  st.bg = 0x0000u;
   610	  st.em16 = (nlines > 1 ? 26 : 44) * 16;
   611	  st.thick16 = (nlines > 1 ? 2 : 3) * 16;
   612	  st.cx16 = (GC9D01_XRES / 2) * 16;
   613	
   614	  hs_clear(priv->fbmem, GC9D01_STRIDE, GC9D01_XRES, GC9D01_YRES, &st);
   615	
   616	  for (i = 0; i < nlines; i++)
   617	    {
   618	      int32_t total;
   619	
   620	      if (lines[i] == NULL || lines[i][0] == '\0')
   621	        {
   622	          continue;   /* An empty line just leaves the cleared background. */
   623	        }
   624	
   625	      /* Baselines: one line centred, two lines split around the centre. */
   626	
   627	      st.baseline16 = nlines > 1 ?
   628	                      ((GC9D01_YRES / 2) + (i == 0 ? -6 : 30)) * 16 :
   629	                      ((GC9D01_YRES / 2) + 16) * 16;
   630	
   631	      total = hs_measure(lines[i], &st, NULL);
   632	      if (total <= 0)
   633	        {
   634	          return -EINVAL;
   635	        }
   636	
   637	      hs_stroke(priv->fbmem, GC9D01_STRIDE, GC9D01_XRES, GC9D01_YRES,
   638	                lines[i], &st, 0, total);
   639	    }
   640	
   641	  return gc9d01_push(priv);
   642	}
