   662	/****************************************************************************
   663	 * Name: bk7258_gc9d01_fb_test_pattern
   664	 *
   665	 * Description:
   666	 *   Draws four quadrants (red / green / blue / white) with a black border.
   667	 *   Colour order and geometry are both wrong-detectable by eye: a swapped
   668	 *   byte order turns red into something else, and a stride mistake shears
   669	 *   the quadrant boundaries.
   670	 *
   671	 ****************************************************************************/
   672	
   673	int bk7258_gc9d01_fb_test_pattern(int display)
   674	{
   675	  FAR struct gc9d01_fb_s *priv;
   676	  FAR uint16_t *px;
   677	  int x;
   678	  int y;
   679	
   680	  if (display < 0 || display >= GC9D01_NDISPLAYS)
   681	    {
   682	      return -EINVAL;
   683	    }
   684	
   685	  priv = &g_gc9d01_fb[display];
   686	  px = (FAR uint16_t *)priv->fbmem;
   687	
   688	  if (px == NULL)
   689	    {
   690	      return -ENODEV;
   691	    }
   692	
   693	  for (y = 0; y < GC9D01_YRES; y++)
   694	    {
   695	      for (x = 0; x < GC9D01_XRES; x++)
   696	        {
   697	          uint16_t c;
   698	
   699	          if (x < 4 || y < 4 || x >= GC9D01_XRES - 4 ||
   700	              y >= GC9D01_YRES - 4)
   701	            {
   702	              c = 0x0000;                                  /* black edge */
   703	            }
   704	          else if (y < GC9D01_YRES / 2)
   705	            {
   706	              c = (x < GC9D01_XRES / 2) ? 0xf800 : 0x07e0;  /* red green */
   707	            }
   708	          else
   709	            {
   710	              c = (x < GC9D01_XRES / 2) ? 0x001f : 0xffff;  /* blue white */
   711	            }
   712	
   713	          px[y * GC9D01_XRES + x] = c;
   714	        }
   715	    }
   716	
   717	  printf("gc9d01_fb[%d]: test pattern drawn (TL red, TR green, BL blue, "
   718	         "BR white, 4px black border)\n", display);
   719	
   720	  return gc9d01_push(priv);
   721	}
