394	   * /dev/fb<display>.
395	   *
396	   * Both panels are registered unconditionally.  GC9D01 has no readable ID
397	   * register, so an unpopulated footprint cannot be distinguished from a
398	   * working panel -- every command still "completes".  Registering /dev/fb1
399	   * on a single-panel board therefore costs one unused 51200-byte buffer
400	   * and nothing else; refusing to register it would need board-variant
401	   * configuration that this board provides no way to detect.
402	   */
403	
404	  {
405	    int display;
406	    int registered = 0;
407	
408	    /* Both panels through reset and the command table in one pass, before
409	     * fb_register() asks for either of them.  The sequence is nearly all
410	     * waiting (20ms rail, 230ms reset pulse, 120ms after Sleep Out) and the
411	     * waits are the panels', not the bus's, so sharing them across the two
412	     * panels takes ~350ms off the time to the first pixel.  fb_register()
413	     * still calls up_fbinitialize() -> bk7258_gc9d01_panel_init(), which
414	     * finds its panel already up and returns.
415	     */
416	
417	    (void)bk7258_gc9d01_panels_init((1 << GC9D01_NDISPLAYS) - 1);
418	
419	    for (display = 0; display < GC9D01_NDISPLAYS; display++)
420	      {
421	        ret = fb_register(display, 0);
422	        if (ret < 0)
423	          {
424	            printf("fb_register(%d) failed: %d\n", display, ret);
425	            continue;
426	          }
427	
428	        registered |= 1 << display;
429	        printf("fb: /dev/fb%d registered\n", display);
430	      }
