   121	void __attribute__((noinline, target("general-regs-only")))
   122	bk7258_cpu_private_initialize(bool primary)
   123	{
   124	  const size_t region_count = sizeof(g_bk7258_mpu_regions) /
   125	                              sizeof(g_bk7258_mpu_regions[0]);
   126	
   127	  modifyreg32(NVIC_CPACR, 0,
   128	              NVIC_CPACR_CP_FULL(10) | NVIC_CPACR_CP_FULL(11));
   129	  UP_DSB();
   130	  UP_ISB();
   131	
   132	  putreg32(0, BK7258_SAU_BASE + 0x08);
   133	  putreg32(0x00000000u, BK7258_SAU_BASE + 0x0c);
   134	  putreg32(0x0fffffe3u, BK7258_SAU_BASE + 0x10);
   135	  putreg32(1, BK7258_SAU_BASE + 0x08);
   136	  putreg32(0x10000000u, BK7258_SAU_BASE + 0x0c);
   137	  putreg32(0xefffffe1u, BK7258_SAU_BASE + 0x10);
   138	  putreg32(1, BK7258_SAU_BASE + 0x00);
   139	  UP_DSB();
   140	  UP_ISB();
   141	
   142	  putreg32((uintptr_t)__ram_vectors_start, NVIC_VECTAB);
   143	  UP_DSB();
   144	  UP_ISB();
   145	
   146	#ifdef CONFIG_ARM_MPU
   147	  {
   148	    const uint32_t hardware_regions =
   149	      (getreg32(MPU_TYPE) & MPU_TYPE_DREGION_MASK) >>
   150	      MPU_TYPE_DREGION_SHIFT;
   151	
   152	    if (hardware_regions < region_count)
   153	      {
   154	        for (; ; )
   155	          {
   156	            __asm__ volatile("wfi");
   157	          }
   158	      }
   159	
   160	    mpu_reset();
   161	    mpu_initialize(g_bk7258_mpu_regions, region_count, false, true);
   162	
   163	#ifdef CONFIG_ARMV8M_ICACHE
   164	    /* Turn the I-Cache on now that the MPU says the flash region is
   165	     * write-through cacheable.
   166	     *
   167	     * The AP executes in place from QSPI flash at 0x02150000, and nothing
   168	     * used to enable this: setting CONFIG_ARMV8M_ICACHE alone only compiles
   169	     * up_enable_icache() in, it does not call it, and every other ARMv8-M
