   176	     * CLIDR reads 0x09200003 on this part, so the cache is really there.
   177	     * Only the I-Cache is enabled: instruction fetch is read-only, so it
   178	     * needs no maintenance against the camera, panel and mailbox DMA that
   179	     * shares AP RAM (which the MPU keeps non-cacheable for that reason).
   180	     */
   181	
   182	    up_enable_icache();
   183	#endif
   184	
   185	  }
   186	#endif
   187	
   188	  (void)primary;
