   206	    {
   207	      *dest++ = *src++;
   208	    }
   209	
   210	  for (dest = _sbss; dest < _ebss; )
   211	    {
   212	      *dest++ = 0;
   213	    }
   214	
   215	  for (src = __ram_vectors_load, dest = __ram_vectors_start;
   216	       dest < __ram_vectors_end; )
   217	    {
   218	      *dest++ = *src++;
   219	    }
