   271	      g_state = BK7258_PSRAM_ONLINE;
   272	      nxmutex_unlock(&g_psram_lock);
   273	      return -EBUSY;
   274	    }
   275	
   276	  for (i = 0; i < BK7258_PSRAM_POOL_COUNT; i++)
   277	    {
   278	      if (g_pool_allocations[i] != 0)
   279	        {
   280	          g_state = BK7258_PSRAM_ONLINE;
   281	          nxmutex_unlock(&g_psram_lock);
   282	          return -EBUSY;
   283	        }
   284	    }
   285	
   286	  mm_uninitialize(g_psram_heap);
   287	  g_psram_heap = NULL;
   288	  for (i = 0; i < BK7258_PSRAM_POOL_COUNT; i++)
   289	    {
   290	      mm_uninitialize(g_pool_heap[i]);
   291	      g_pool_heap[i] = NULL;
   292	    }
   293	
   294	  g_state = BK7258_PSRAM_OFFLINE;
   295	  nxmutex_unlock(&g_psram_lock);
   296	  return OK;
   297	}
