1059	int bk7258_bt_transport_send(enum bt_buf_type_e type,
1060	                             const void *data, size_t length)
1061	{
1062	  uint8_t packet_type;
1063	  irqstate_t flags;
1064	  bool enabled;
1065	  int ret;
1066	
1067	  if (data == NULL || length > BLUETOOTH_MAX_FRAMELEN)
1068	    {
1069	      return -EINVAL;
1070	    }
1071	
1072	  flags = spin_lock_irqsave(&g_lock);
1073	  enabled = g_host_enabled;
1074	  spin_unlock_irqrestore(&g_lock, flags);
1075	  if (!enabled)
1076	    {
1077	      return -ESHUTDOWN;
1078	    }
1079	
1080	  if (type == BT_CMD)
1081	    {
1082	      const uint8_t *command = data;
1083	      uint16_t opcode;
1084	
1085	      if (length < 3 || command[2] != length - 3)
1086	        {
1087	          return -EMSGSIZE;
1088	        }
1089	
1090	      packet_type = BK7258_BT_HCI_COMMAND_PKT;
1091	      opcode = bt_get_le16(command);
1092	      /* printf("bt-ipc: tx-cmd opcode=%04x len=%lu\n",
1093	             (unsigned int)opcode, (unsigned long)length); */
1094	
1095	      if (opcode == BT_HCI_OP_HOST_BUFFER_SIZE)
1096	        {
1097	          bt_inject_command_complete(opcode);
1098	          return (int)length;
1099	        }
1100	
1101	      if (opcode == BT_HCI_OP_HOST_NUM_COMPLETED_PACKETS)
1102	        {
1103	          return (int)length;
1104	        }
1105	
1106	    }
1107	  else if (type == BT_ACL_OUT)
1108	    {
1109	      const uint8_t *acl = data;
1110	
1111	      if (length < 4 || bt_get_le16(&acl[2]) != length - 4)
1112	        {
1113	          return -EMSGSIZE;
1114	        }
1115	
1116	      packet_type = BK7258_BT_HCI_ACL_DATA_PKT;
1117	      printf("bt-ipc: tx-acl len=%lu\n", (unsigned long)length);
1118	    }
1119	  else
1120	    {
1121	      return -EINVAL;
1122	    }
1123	
1124	  ret = bt_enqueue_pool(data, length, packet_type, false, type == BT_CMD,
1125	                        NULL, NULL);
1126	  return ret < 0 ? ret : (int)length;
1127	}
