   191	          ret = open_blockdriver("/dev/mmcsd0", MS_RDONLY, &inode);
   192	          if (ret != -ENOENT)
   193	            {
   194	              break;
   195	            }
   196	        }
   197	    }
   198	
   199	  if (ret < 0)
   200	    {
   201	      printf("MMCSD probe did not register /dev/mmcsd0, error=%d\n", ret);
   202	      return ret;
   203	    }
   204	
   205	  close_blockdriver(inode);
   206	
   207	  printf("SD-NAND MMCSD ready: /dev/mmcsd0\n");
   208	
   209	#ifdef CONFIG_MBR_PARTITION
   210	  g_partition_result = -ENOENT;
   211	  ret = parse_block_partition("/dev/mmcsd0", bk7258_partition_handler, NULL);
   212	  if (ret < 0)
   213	    {
   214	      printf("SD-NAND has no parseable MBR, using super-floppy path: %d\n",
   215	             ret);
   216	    }
   217	#endif
   218	
   219	#ifdef CONFIG_BK7258_SDNAND_AUTOMOUNT
   220	  ret = bk7258_mmcsd_mount_locked(NULL);
   221	  if (ret < 0)
   222	    {
   223	      printf("SD-NAND initialized without persistent mount, error=%d\n",
   224	             ret);
   225	    }
   226	#endif
   227	
   228	  return OK;
   229	}
