   231	int bk7258_mmcsd_initialize(void)
   232	{
   233	  FAR struct inode *inode;
   234	  int ret;
   235	
   236	  ret = nxmutex_lock(&g_mmcsd_lock);
   237	  if (ret < 0)
   238	    {
   239	      return ret;
   240	    }
   241	
   242	  if (g_mmcsd_state == BK7258_MMCSD_COMPLETE)
   243	    {
   244	      ret = open_blockdriver("/dev/mmcsd0", MS_RDONLY, &inode);
   245	      if (ret == OK)
   246	        {
   247	          close_blockdriver(inode);
   248	#ifdef CONFIG_BK7258_SDNAND_AUTOMOUNT
   249	          if (!g_mmcsd_mounted)
   250	            {
   251	              ret = bk7258_mmcsd_mount_locked(NULL);
   252	            }
   253	#endif
   254	        }
   255	      else
   256	        {
   257	          ret = g_mmcsd_result;
   258	        }
   259	
   260	      nxmutex_unlock(&g_mmcsd_lock);
   261	      return ret;
   262	    }
   263	
   264	  g_mmcsd_state = BK7258_MMCSD_RUNNING;
   265	  ret = bk7258_mmcsd_probe();
   266	  g_mmcsd_result = ret;
   267	  g_mmcsd_state = BK7258_MMCSD_COMPLETE;
   268	  nxmutex_unlock(&g_mmcsd_lock);
   269	  return ret;
   270	}
