   299	int bk7258_mmcsd_maintenance_begin(void)
   300	{
   301	  char path[sizeof("/dev/mmcsd0p0")];
   302	  unsigned int index;
   303	  int ret;
   304	
   305	  ret = nxmutex_lock(&g_mmcsd_lock);
   306	  if (ret < 0)
   307	    {
   308	      return ret;
   309	    }
   310	
   311	  if (g_mmcsd_state != BK7258_MMCSD_COMPLETE ||
   312	      !bk7258_block_exists("/dev/mmcsd0"))
   313	    {
   314	      ret = -ENODEV;
   315	      goto out_unlock;
   316	    }
   317	
   318	  if (g_mmcsd_maintenance)
   319	    {
   320	      ret = -EBUSY;
   321	      goto out_unlock;
   322	    }
   323	
   324	  g_mmcsd_maintenance = true;
   325	  if (g_mmcsd_mounted)
   326	    {
   327	      ret = nx_umount2(CONFIG_BK7258_SDNAND_MOUNTPOINT, 0);
   328	      if (ret < 0)
   329	        {
   330	          g_mmcsd_maintenance = false;
   331	          goto out_unlock;
   332	        }
   333	
   334	      g_mmcsd_mounted = false;
   335	      g_mount_source[0] = '\0';
   336	    }
   337	
   338	  for (index = 0; index < 10; index++)
   339	    {
   340	      snprintf(path, sizeof(path), "/dev/mmcsd0p%u", index);
   341	      if (bk7258_block_exists(path))
   342	        {
   343	          ret = unregister_blockdriver(path);
   344	          if (ret < 0)
   345	            {
   346	              printf("SD-NAND partition quarantine failed: %s error=%d\n",
   347	                     path, ret);
   348	              g_mmcsd_maintenance = false;
   349	              goto out_unlock;
   350	            }
   351	        }
   352	    }
   353	
   354	  g_partition_result = -ENOENT;
   355	
   356	  ret = OK;
   357	
   358	out_unlock:
   359	  nxmutex_unlock(&g_mmcsd_lock);
   360	  return ret;
   361	}
