   465	int bk7258_mmcsd_schedule(unsigned int delay_ms)
   466	{
   467	  int ret;
   468	
   469	  ret = nxmutex_lock(&g_mmcsd_lock);
   470	  if (ret < 0)
   471	    {
   472	      return ret;
   473	    }
   474	
   475	  if (g_mmcsd_state != BK7258_MMCSD_NOT_STARTED ||
   476	      !work_available(&g_mmcsd_work))
   477	    {
   478	      nxmutex_unlock(&g_mmcsd_lock);
   479	      return OK;
   480	    }
   481	
   482	  ret = work_queue(LPWORK, &g_mmcsd_work, bk7258_mmcsd_worker, NULL,
   483	                   MSEC2TICK(delay_ms));
   484	  nxmutex_unlock(&g_mmcsd_lock);
   485	
   486	  if (ret == OK)
   487	    {
   488	      printf("SD-NAND initialization scheduled in %u ms\n", delay_ms);
   489	    }
   490	
   491	  return ret;
   492	}
